mapper.select:
SELECT n.id, n.user_id, n.title, n.cover_url, n.latitude, n.longitude, n.place_name, n.created_at, u.nickname AS author_nickname FROM notes n INNER JOIN users u ON u.id = n.user_id AND u.status = 1 WHERE n.visibility = 1 AND n.latitude IS NOT NULL AND n.longitude IS NOT NULL AND n.latitude BETWEEN #{minLat} AND #{maxLat} AND n.longitude BETWEEN #{minLng} AND #{maxLng}
/* P18 屏蔽双向过滤 */ AND NOT EXISTS (SELECT 1 FROM user_blocks b WHERE (b.user_id = #{viewerId} AND b.blocked_user_id = n.user_id) OR (b.user_id = n.user_id AND b.blocked_user_id = #{viewerId}))
AND (n.created_at < #{cursorCreatedAt} OR (n.created_at = #{cursorCreatedAt} AND n.id < #{cursorId}))
ORDER BY n.created_at DESC, n.id DESC LIMIT #{limit}
